Item.method_code:
            Innovator inn = this.getInnovator();

            try
            {
                //初回保存時、対象マルQページと対象必要資料に値がある場合、必要資料がロックされているかチェックする
                
                var thisId = this.getID();
                var h4_rel_mq = this.getProperty("h4_rel_mq","");
                var h4_rel_reqdoc = this.getProperty("h4_rel_reqdoc","");
                var h4_point_sub_number = this.getProperty("h4_point_sub_number","");
                
                //枝番が1のときのみ有効
                if(h4_point_sub_number != "1")
                {
                    return this;
                }
                
                //対象マルQページと対象必要資料に値がある場合、このアイテムを必要資料に紐づける。
                if (!string.IsNullOrEmpty(h4_rel_mq) && !string.IsNullOrEmpty(h4_rel_reqdoc))
                {
                    //必要資料がロックされていない場合は、エラーとする
                    var reDocItem = inn.getItemById("h4_ReqDoc", h4_rel_reqdoc);
                    
                    var lockStatus = reDocItem.fetchLockStatus();
                    if(lockStatus != 0)
                    {
                      return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0603"));                   
                    }
                }
                
                return this;
            }
            catch (Exception e)
            {
                // Item err = inn.newError("Error011:" + e.Message);
                // err.setErrorDetail(e.StackTrace);
                // return err;
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
            }
        }

